-- Frozen differential fixtures generated from real NumPy 2.3.5
local np=require("luaray_core")
assert(np._version=="0.99.0-dev")
local checks,cases=0,0
local function deep(a,b,desc)
    assert(type(a)==type(b),desc..': type mismatch: '..type(a)..' vs '..type(b))
    if type(a)=='table' then
        assert(#a==#b,desc..': length mismatch: '..#a..' vs '..#b)
        for i=1,#a do deep(a[i],b[i],desc..'['..i..']') end
    else
        assert(a==b,desc..': '..tostring(a)..' vs '..tostring(b))
    end
    checks=checks+1
end
do
local r=np.random.default_rng(1)
local x=np.transpose(np.astype(np.arange(18,"int64"):reshape({3,2,3}),"float32"),{3,2,1})
local before=x:tolist()
local y=r:permuted(x,nil)
deep(y.dtype,"float32","1/(3, 2, 3)/float32/transpose/None/copy dtype")
deep(y:tolist(),{{{12.0,16.0,0.0},{15.0,4.0,17.0}},{{1.0,14.0,9.0},{10.0,5.0,13.0}},{{11.0,3.0,2.0},{7.0,8.0,6.0}}},"1/(3, 2, 3)/float32/transpose/None/copy values")
deep(x:tolist(),{{{0.0,6.0,12.0},{3.0,9.0,15.0}},{{1.0,7.0,13.0},{4.0,10.0,16.0}},{{2.0,8.0,14.0},{5.0,11.0,17.0}}},"1/(3, 2, 3)/float32/transpose/None/copy source")
deep(r:raw_hex(),"89c3c29ad67f9ca4","1/(3, 2, 3)/float32/transpose/None/copy pcg")
cases=cases+1; end
