local x=np.astype(np.arange(8,"int64"):reshape({2,1,4}),"int32")
local before=x:tolist()
local y=r:permuted(x,-1)
deep(y.dtype,"int32","1/(2, 1, 4)/int32/plain/-1/copy dtype")
deep(y:tolist(),{{{0,1,2,3}},{{7,4,6,5}}},"1/(2, 1, 4)/int32/plain/-1/copy values")
deep(x:tolist(),{{{0,1,2,3}},{{4,5,6,7}}},"1/(2, 1, 4)/int32/plain/-1/copy source")
deep(r:raw_hex(),"4fd42fa03fcd72a9","1/(2, 1, 4)/int32/plain/-1/copy pcg")
cases=cases+1; end
