local y=r:permuted(x,3)
deep(y.dtype,"uint8","1/(1, 2, 4)/uint8/flip/2/copy dtype")
deep(y:tolist(),{{{0,1,2,3},{7,4,6,5}}},"1/(1, 2, 4)/uint8/flip/2/copy values")
deep(x:tolist(),{{{0,1,2,3},{4,5,6,7}}},"1/(1, 2, 4)/uint8/flip/2/copy source")
deep(r:raw_hex(),"4fd42fa03fcd72a9","1/(1, 2, 4)/uint8/flip/2/copy pcg")
cases=cases+1; end
