local x=np.astype(np.arange(12,"int64"):reshape({2,3,1,2}),"int64")
local before=x:tolist()
local y=r:permuted(x,4,x)
deep(y.dtype,"int64","1/(2, 3, 1, 2)/int64/plain/3/out_same dtype")
deep(y:tolist(),{{{{0,1}},{{2,3}},{{5,4}}},{{{6,7}},{{8,9}},{{11,10}}}},"1/(2, 3, 1, 2)/int64/plain/3/out_same values")
